(function() {
    'use strict';

    class CrisisManagementAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Social Media Crisis Management: The NUBA Crisis';
            this.version = '1.1.0';

            this.PHASES = [
                {
                    titleKey: 'phase1_title',
                    icon: '🚨',
                    briefing: 'A consumer, Ana García (47,000 TikTok followers, food blogger, mother of two), has posted a 45-second video showing a metallic fragment inside a NUBA Natural Mango & Chia bar. She says: "I almost gave this to my daughter. She is four years old. This is the third time I found something strange in NUBA products this month." The video has 12,000 views and climbing. A journalist at El Universal has tweeted about it. Your social listening tool shows a 340% spike in negative mentions.',
                    mentions: '340% above baseline',
                    media: 'One journalist tweet',
                    viral: '12,000 views (growing)'
                },
                {
                    titleKey: 'phase2_title',
                    icon: '📢',
                    briefing: 'The video has reached 85,000 views. Two food safety accounts with 200,000+ followers have shared it. Quality control confirms the product lot was produced at the Guadalajara facility. Customer service records reveal TWO previous complaints about foreign objects in the past 30 days, both dismissed as user error. The fragment appears consistent with a metallic seal from packaging machinery. No injuries reported. You must craft your first full public response across multiple platforms.',
                    mentions: '1,200% above baseline',
                    media: 'Active journalist investigation',
                    viral: '85,000 views'
                },
                {
                    titleKey: 'phase3_title',
                    icon: '⚠️',
                    briefing: 'Testing reveals 3 additional units from the same batch contain microscopic metallic fragments. The fragments are below mandatory COFEPRIS recall threshold but above internal NUBA quality standards. Key influencers have weighed in: @Mama_Saludable_Mexico (620K followers) is watching, @FoodNerdMX (180K) is providing fair but skeptical analysis, and @ConsumidorAlerta (95K) is attacking the brand. You must decide on a product recall and manage internal communications for 2,400 employees across 12 countries.',
                    mentions: '2,800% above baseline',
                    media: 'El Universal article published',
                    viral: '220,000+ total views'
                },
                {
                    titleKey: 'phase4_title',
                    icon: '🔥',
                    briefing: 'The crisis has reached peak intensity. Mainstream media coverage is widespread. A random development has complicated the situation further. You must manage this new development while maintaining your crisis strategy. Consider whether the CEO should make a personal statement and what tangible commitments NUBA will make to affected consumers and to preventing recurrence.',
                    mentions: 'Peak volume',
                    media: 'Mainstream broadcast coverage',
                    viral: '500,000+ total reach'
                },
                {
                    titleKey: 'phase5_title',
                    icon: '🌿',
                    briefing: 'The acute crisis is subsiding. Mention volume is declining from its peak. You must navigate the transition from crisis defense to active trust rebuilding. Decide when to resume normal marketing communications. Design a recovery content strategy that demonstrates transparency without appearing promotional. Make permanent structural commitments that signal genuine organizational learning, not just tactical fixes.',
                    mentions: 'Declining from peak',
                    media: 'One ongoing investigative piece',
                    viral: 'Stabilizing'
                }
            ];

            this.EVENTS = [
                'CEO MEDIA REQUEST: The morning anchor of Televisa Noticias requests a live 5-minute interview with the CEO in 3 hours. Accept or decline? Your response speed and empathy will determine how the interview narrative develops.',
                'COMPETITOR EXPLOITATION: LimpiaNatural has tweeted: "At LimpiaNatural, every ingredient and every process is certified by an independent laboratory. What you see is what you get." A subtle but unmistakable crisis-exploiting message.',
                'REGULATORY CONTACT: COFEPRIS has requested documentation of all quality control processes and batch records for the affected product line within 48 hours. Your transparency level determines regulatory relationship outcome.',
                'SECOND VIRAL VIDEO: A consumer in Colombia has published a video showing what appears to be an insect fragment in a different NUBA Natural product. Already at 40,000 views. The crisis is no longer geographically contained.',
                'EMPLOYEE LEAK: A production line worker posted on Facebook: "We have known about the machine maintenance issues for months. Management told us to keep production going." The post has 3,400 shares and climbing.'
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    sentiment: -65,
                    brandTrust: 50,
                    stakeholderScore: 0,
                    crisisBudget: 500000,
                    speedDimension: 0,
                    coherenceDimension: 0,
                    stakeholderDimension: 0,
                    recoveryDimension: 0,
                    sentimentHistory: [],
                    trustHistory: [],
                    stakeholderHistory: [],
                    budgetHistory: [],
                    previousTransparency: 0,
                    previousEmpathy: 0,
                    activeEvent: '',
                    activeEventIndex: -1,
                    totalSpent: 0,
                    phaseScores: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    speed: 5,
                    transparency: 5,
                    empathy: 5,
                    stakeholderFocus: 5,
                    budget: 50000
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var speedInput = document.getElementById('speedInput');
            if (speedInput) decisions.speed = parseInt(speedInput.value);

            var transparencyInput = document.getElementById('transparencyInput');
            if (transparencyInput) decisions.transparency = parseInt(transparencyInput.value);

            var empathyInput = document.getElementById('empathyInput');
            if (empathyInput) decisions.empathy = parseInt(empathyInput.value);

            var stakeholderInput = document.getElementById('stakeholderInput');
            if (stakeholderInput) decisions.stakeholderFocus = parseInt(stakeholderInput.value);

            var budgetInput = document.getElementById('budgetInput');
            if (budgetInput) decisions.budget = parseInt(budgetInput.value);

            if (!decisions.speed || decisions.speed < 1 || decisions.speed > 10) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('speed_warning'), 'warning'
                );
                return false;
            }

            if (!decisions.budget || decisions.budget < 10000 || decisions.budget > 200000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }

            var _st = window.mySimulation && window.mySimulation.state; var remaining = _st && _st.domainState ? _st.domainState.crisisBudget : 500000;
            if (decisions.budget > remaining) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_exceed'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var phase = state.currentPeriod;

            var speedEffect = 0;
            var transparencyEffect = 0;
            var empathyEffect = 0;
            var stakeholderEffect = 0;
            var eventModifier = 0;

            if (phase === 1) {
                speedEffect = (d.speed >= 8) ? 15 : (d.speed >= 6) ? 10 : (d.speed >= 4) ? 3 : -5;
                transparencyEffect = (d.transparency - 5) * 1.2;
                empathyEffect = (d.empathy - 5) * 1.5;
                stakeholderEffect = (d.stakeholderFocus >= 7) ? 5 : (d.stakeholderFocus >= 4) ? 2 : -3;

                ds.speedDimension = (d.speed >= 8) ? 15 : (d.speed >= 6) ? 12 : (d.speed >= 4) ? 8 : 4;
            } else if (phase === 2) {
                speedEffect = (d.speed >= 7) ? 12 : (d.speed >= 5) ? 6 : -3;
                transparencyEffect = (d.transparency - 5) * 2.0;
                empathyEffect = (d.empathy - 5) * 2.5;
                stakeholderEffect = (d.stakeholderFocus >= 7) ? 8 : (d.stakeholderFocus >= 4) ? 3 : -5;
            } else if (phase === 3) {
                speedEffect = (d.speed - 5) * 1.0;
                transparencyEffect = (d.transparency >= 7) ? 10 : (d.transparency >= 5) ? 4 : -6;
                empathyEffect = (d.empathy >= 7) ? 10 : (d.empathy >= 5) ? 4 : -8;
                stakeholderEffect = (d.stakeholderFocus >= 6) ? 10 : (d.stakeholderFocus >= 4) ? 4 : -6;

                var eventIdx = Math.floor(Math.random() * this.EVENTS.length);
                ds.activeEvent = this.EVENTS[eventIdx];
                ds.activeEventIndex = eventIdx;

                if (eventIdx === 3) {
                    eventModifier = -8;
                } else if (eventIdx === 4) {
                    eventModifier = (ds.stakeholderHistory.length > 0 && d.stakeholderFocus >= 7) ? -2 : -12;
                } else if (eventIdx === 0) {
                    eventModifier = (d.empathy >= 7 && d.transparency >= 7) ? 5 : -5;
                } else if (eventIdx === 1) {
                    eventModifier = (d.speed <= 3) ? -6 : -2;
                } else {
                    eventModifier = (d.transparency >= 7) ? 3 : -5;
                }
            } else if (phase === 4) {
                speedEffect = (d.speed - 5) * 0.8;
                transparencyEffect = (d.transparency >= 8) ? 12 : (d.transparency >= 6) ? 6 : -4;
                empathyEffect = (d.empathy >= 8) ? 14 : (d.empathy >= 6) ? 7 : -6;
                stakeholderEffect = (d.stakeholderFocus >= 7) ? 8 : (d.stakeholderFocus >= 4) ? 3 : -5;

                if (ds.activeEventIndex === 3) {
                    eventModifier = (d.transparency >= 8) ? 4 : -6;
                } else if (ds.activeEventIndex === 4) {
                    eventModifier = (d.empathy >= 8 && d.stakeholderFocus >= 7) ? 6 : -8;
                }
            } else {
                speedEffect = (d.speed >= 4 && d.speed <= 7) ? 6 : -3;
                transparencyEffect = (d.transparency >= 8) ? 12 : (d.transparency >= 6) ? 6 : -4;
                empathyEffect = (d.empathy >= 7) ? 8 : (d.empathy >= 5) ? 4 : -4;
                stakeholderEffect = (d.stakeholderFocus >= 6) ? 8 : 2;
            }

            var consistencyBonus = 0;
            if (ds.previousTransparency > 0) {
                var transDiff = Math.abs(d.transparency - ds.previousTransparency);
                var empDiff = Math.abs(d.empathy - ds.previousEmpathy);
                if (transDiff <= 2 && empDiff <= 2) {
                    consistencyBonus = 4;
                } else if (transDiff >= 5 || empDiff >= 5) {
                    consistencyBonus = -6;
                }
            }

            var budgetEffect = 0;
            var budgetRatio = d.budget / 200000;
            if (phase <= 2) {
                budgetEffect = budgetRatio * 5;
            } else if (phase === 3) {
                budgetEffect = budgetRatio * 8;
            } else if (phase === 4) {
                budgetEffect = budgetRatio * 6;
            } else {
                budgetEffect = budgetRatio * 4;
            }

            var sentimentChange = speedEffect + transparencyEffect + empathyEffect + eventModifier + consistencyBonus + budgetEffect;

            var trustChange = (empathyEffect * 0.6) + (transparencyEffect * 0.8) + (consistencyBonus * 0.5) + (budgetEffect * 0.3);

            var phaseStakeholderScore = stakeholderEffect + (d.empathy >= 7 ? 3 : 0) + (d.stakeholderFocus >= 7 ? 4 : 0);

            ds.sentiment = Math.max(-100, Math.min(100, ds.sentiment + sentimentChange));
            ds.brandTrust = Math.max(0, Math.min(100, ds.brandTrust + trustChange));
            ds.stakeholderScore += phaseStakeholderScore;
            ds.crisisBudget -= d.budget;
            ds.totalSpent += d.budget;

            ds.sentimentHistory.push(Math.round(ds.sentiment));
            ds.trustHistory.push(Math.round(ds.brandTrust));
            ds.stakeholderHistory.push(phaseStakeholderScore);
            ds.budgetHistory.push(d.budget);

            ds.previousTransparency = d.transparency;
            ds.previousEmpathy = d.empathy;

            if (phase >= 2) {
                ds.coherenceDimension += (consistencyBonus > 0 ? 5 : (consistencyBonus < 0 ? -3 : 1));
            }
            ds.stakeholderDimension += phaseStakeholderScore;

            if (phase === 5) {
                var recoveryQ = 0;
                recoveryQ += (d.transparency >= 8) ? 6 : (d.transparency >= 6) ? 3 : 0;
                recoveryQ += (d.empathy >= 7) ? 5 : (d.empathy >= 5) ? 2 : 0;
                recoveryQ += (d.speed >= 4 && d.speed <= 7) ? 4 : 0;
                ds.recoveryDimension = recoveryQ;
            }

            var phaseScore = Math.round(sentimentChange + trustChange + phaseStakeholderScore);
            ds.phaseScores.push(phaseScore);

            var self = this;
            var nextPeriod = (state.currentPeriod || 1) + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 500);

            return {
                period: phase,
                sentimentChange: Math.round(sentimentChange),
                trustChange: Math.round(trustChange),
                stakeholderGain: Math.round(phaseStakeholderScore),
                sentiment: Math.round(ds.sentiment),
                brandTrust: Math.round(ds.brandTrust),
                budgetSpent: d.budget,
                phaseScore: phaseScore,
                eventModifier: Math.round(eventModifier)
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('sentimentDisplay', 'domainState.sentiment', function(v) { return Math.round(v); });
            uiManager.bind('trustDisplay', 'domainState.brandTrust', function(v) { return Math.round(v); });
            uiManager.bind('stakeholderDisplay', 'domainState.stakeholderScore', function(v) { return Math.round(v); });
            uiManager.bind('budgetDisplay', 'domainState.crisisBudget', function(v) { return '$' + Math.round(v).toLocaleString(); });

            var sliders = ['speedInput', 'transparencyInput', 'empathyInput', 'stakeholderInput'];
            var valueSpans = ['speedValue', 'transparencyValue', 'empathyValue', 'stakeholderValue'];
            sliders.forEach(function(id, i) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() {
                        var span = document.getElementById(valueSpans[i]);
                        if (span) span.textContent = el.value;
                    });
                }
            });
            var self = this;
            var undoBtn = document.getElementById('undoBtn');
            if (undoBtn) { undoBtn.addEventListener('click', function() { if (window.mySimulation && window.mySimulation.state) self._updateBriefing(window.mySimulation.state); }); }
        }

        getChartConfig() {
            return {
                sentimentChart: {
