        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds = last.domainState || {};

            var speedScore = ds.speedDimension || 0;
            var coherenceBase = ds.coherenceDimension || 0;
            var coherenceScore = Math.max(0, Math.min(25, 12 + coherenceBase));
            var stakeholderBase = ds.stakeholderDimension || 0;
            var stakeholderScore = Math.max(0, Math.min(20, 10 + Math.round(stakeholderBase * 0.5)));

            var sentimentStart = -65;
            var sentimentEnd = ds.sentiment || -65;
            var sentimentRecovery = sentimentEnd - sentimentStart;
            var sentimentScore = Math.max(0, Math.min(25, Math.round(sentimentRecovery * 0.25 + 12)));

            var recoveryScore = Math.max(0, Math.min(15, ds.recoveryDimension || 0));

            var totalScore = speedScore + coherenceScore + stakeholderScore + sentimentScore + recoveryScore;

            var performance = 'Crisis Novice';
            if (totalScore >= 80) performance = 'Master Crisis Manager';
            else if (totalScore >= 65) performance = 'Skilled Communicator';
            else if (totalScore >= 50) performance = 'Competent Responder';
            else if (totalScore >= 35) performance = 'Developing Practitioner';

            var insights = [];
            if (speedScore >= 12) {
                insights.push('Strong first-response speed. You understood the 60-minute rule and acted before external voices dominated the narrative.');
            } else {
                insights.push('Slow initial response. In social media crises, silence reads as indifference. A holding statement within the first hour is critical.');
            }
            if (coherenceScore >= 18) {
                insights.push('Excellent strategy coherence. Consistent transparency and empathy across phases builds credible commitment.');
            } else {
                insights.push('Strategy inconsistency across phases reduced credibility. SCCT prescribes maintaining your chosen response strategy throughout the crisis.');
            }
            if (sentimentEnd > -10) {
                insights.push('Strong sentiment recovery. You navigated the crisis toward resolution effectively.');
            } else {
                insights.push('Sentiment remains deeply negative. Consider whether higher transparency and empathy could have accelerated recovery.');
            }
            if (stakeholderScore >= 14) {
                insights.push('Effective stakeholder management. Prioritizing affected consumers and employees over media management aligns with crisis management best practice.');
            }
            if (recoveryScore >= 10) {
                insights.push('Your recovery plan demonstrates double-loop organizational learning, not just tactical fixes.');
            }

            return {
                totalScore: totalScore,
                speedScore: speedScore,
                coherenceScore: coherenceScore,
                stakeholderScore: stakeholderScore,
                sentimentScore: sentimentScore,
                recoveryScore: recoveryScore,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var phase = state.currentPeriod;

            if (phase === 1 && results.sentimentChange < 5) {
                return window.mySimulation.t('hint_speed');
            }
            if (results.sentimentChange < 0) {
                return window.mySimulation.t('hint_negative');
            }
            if (state.domainState.crisisBudget < 100000) {
                return window.mySimulation.t('hint_budget');
            }
            if (results.trustChange < 0) {
                return window.mySimulation.t('hint_trust');
            }
            if (results.sentimentChange > 15) {
                return window.mySimulation.t('hint_good');
            }
            return null;
        }

